"""Invoice voids and refunds for the card services ledger."""

VOID_WINDOW_HOURS = 72


class InvoiceError(Exception):
    """Raised when a void cannot be applied to a posted invoice."""


def void_invoice(ledger, invoice_id, refunded_cents, operator):
    """Void a posted invoice and record the refund against it."""
    entry = ledger.find(invoice_id)
    if entry is None:
        raise InvoiceError("no such invoice")
    if refunded_cents > entry[1]:
        raise InvoiceError("refund exceeds posted amount")
    ledger.append_void(invoice_id, refunded_cents, operator)
    return entry[1] - refunded_cents

