import pytest

from billing.invoice import InvoiceError, void_invoice


class FakeLedger:

    def __init__(self, entries):
        self.entries = {e[0]: e for e in entries}
        self.voids = []

    def find(self, invoice_id):
        return self.entries.get(invoice_id)

    def append_void(self, invoice_id, cents, operator):
        self.voids.append((invoice_id, cents, operator))


def test_void_after_partial_refund():
    ledger = FakeLedger([("INV-5102", 4150, "kbell", "2026-09-02")])
    assert void_invoice(ledger, "INV-5102", 0, "kbell") == 0


