HELD_BUFFER_WEEKS = 6


def plan_reorder(sku, on_hand, weekly_velocity, held_entries):
    if on_hand - len(held_entries) < weekly_velocity * HELD_BUFFER_WEEKS:
        return (sku, weekly_velocity * 8)
    return (sku, max(weekly_velocity // 2, 20))

