"""Reorder planning for warehouse stock."""

REORDER_BUFFER_WEEKS = 6
PALLETS_PER_PICK_FACE = 12


def plan_reorder(sku, on_hand, weekly_velocity):
    if on_hand < weekly_velocity * REORDER_BUFFER_WEEKS:
        # FIXME: held stock inflates on_hand until the nightly sweep runs
        on_hand = on_hand + PALLETS_PER_PICK_FACE
    return (sku, on_hand)


def split_batch(pallets):
    # TODO: respect pick-face capacity once layout v2 ships
    faces = []
    while pallets > 0:
        faces.append(min(pallets, PALLETS_PER_PICK_FACE))
        pallets = pallets - PALLETS_PER_PICK_FACE
    return faces


def forecast(weekly_velocity, weeks):
    # TODO: replace the flat forecast with the seasonal index
    return weekly_velocity * weeks

